            raise ValueError('Start ID does not match batch')
        uploader = uploader or Uploader()
        paths = [self.get_abspath(self.item_id, self.batch_id, size) for size in SIZES]
        if any(not os.path.isfile(path) for path in paths):
            return False
        for path in paths:
            with zipfile.ZipFile(path) as archive:
                if archive.testzip() is not None or not count_files_in_zip(path):
                    raise ValueError(f'Invalid or empty ZIP: {path}')
        covers = CoverDB().get_batch_covers(self.item_id, self.batch_id)
        if not covers:
            return False
        for size, path in zip(SIZES, paths):
            with zipfile.ZipFile(path) as archive:
                names = set(archive.namelist())
            missing = [
                row.id for row in covers
                if f'{row.id:010d}{"-" + size.upper() if size else ""}.jpg' not in names
            ]
            if missing:
                raise ValueError(f'{path} is missing {len(missing)} archived covers')
        if not all(uploader.is_uploaded(os.path.basename(os.path.dirname(path)), os.path.basename(path)) for path in paths):
            return False
        CoverDB.update_completed_batch(self.item_id, self.batch_id)
        for path in paths:
            os.remove(path)
        return True


class ZipManager:
    """Append uncompressed covers to their respective batches once."""

    def __init__(self):
        self.zipfiles = {}
        self.names = {}

    def get_zipfile(self, name):
        match = re.fullmatch(r'(\d{10})(?:-([SML]))?\.([a-zA-Z0-9]+)', name)
        if not match:
            raise ValueError(f'Invalid cover filename: {name}')
        cover_id, suffix, _ = match.groups()
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        size = suffix.lower() if suffix else ''
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = archive
            self.names[path] = set(archive.namelist())
        return path, self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        path, archive = self.get_zipfile(name)
        if name not in self.names[path]:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, archive.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            self.names[path].add(name)
        return os.path.relpath(path, config.data_root) + '/' + name

    def close(self):
        for archive in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()
        self.names.clear()


def get_zipfile(name):
    """Open the corresponding ZIP for appending; caller closes it."""
    return open_zipfile(name)


def open_zipfile(name):
    match = re.fullmatch(r'(\d{10})(?:-([SML]))?\.([a-zA-Z0-9]+)', name)
    if not match:
        raise ValueError(f'Invalid cover filename: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
    path = Batch.get_abspath(item_id, batch_id, (match.group(2) or '').lower())
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'], check=True, text=True, capture_output=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], check=True, text=True, capture_output=True)
        found = zip_filename in result.stdout.splitlines()
        if verbose:
            print(f'{item}/{zip_filename}: {"uploaded" if found else "missing"}')
        return found


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return int(start_id) // 10_000 * 10_000 + 9_999

    def get_batch_covers(self, item_id, batch_id):
        item_id, batch_id = Batch._format_ids(item_id, batch_id)
        start = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end = self._get_batch_end_id(start)
        return list(self.db.select(
            'cover', where='id >= $start and id <= $end and archived=$yes and failed=$no',
            vars={'start': start, 'end': end, 'yes': True, 'no': False}, order='id'
        ))

    def get_unarchived(self, limit=10_000):
        return self.db.select('cover', where='archived=$f and failed=$f',
                              order='id', vars={'f': False}, limit=limit)

    def get_archived(self, limit=10_000):
        return self.db.select('cover', where='archived=$yes and uploaded=$no and failed=$no',
                              order='id', vars={'yes': True, 'no': False}, limit=limit)

    def get_failed(self, limit=10_000):
        return self.db.select('cover', where='failed=$yes', order='id',
                              vars={'yes': True}, limit=limit)

    def get_completed(self, limit=10_000):
        return self.db.select('cover', where='uploaded=$yes', order='id',
                              vars={'yes': True}, limit=limit)

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        item_id, batch_id = Batch._format_ids(item_id, batch_id)
        start = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end = CoverDB._get_batch_end_id(start)
        database = db.getdb()
        transaction = database.transaction()
        try:
            rows = database.select('cover', where='id >= $start and id <= $end and archived=$yes and failed=$no',
                                   vars={'start': start, 'end': end, 'yes': True, 'no': False})
            for row in rows:
                database.update('cover', where='id=$id and archived=$yes and failed=$no',
                                vars={'id': row.id, 'yes': True, 'no': False}, uploaded=True,
                                filename=Cover.get_cover_url(row.id, ext=ext),
                                filename_s=Cover.get_cover_url(row.id, 's', ext),
                                filename_m=Cover.get_cover_url(row.id, 'm', ext),
                                filename_l=Cover.get_cover_url(row.id, 'l', ext))
        except Exception:
            transaction.rollback()
            raise
        else:
            transaction.commit()


def archive(test=True):
    """Stage up to 10,000 unarchived covers in ZIPs, one locked batch at a time."""
    database = CoverDB()
    covers = list(database.get_unarchived())
    for row in covers:
        item_id, batch_id = Cover.id_to_item_and_batch_id(row.id)
        batch = Batch(item_id, batch_id)
        with batch.lock():
            current = list(database.db.select('cover', where='id=$id', vars={'id': row.id}))
            if not current or current[0].archived or current[0].failed:
                continue
            row = current[0]
            cover = Cover(row)
            files = list(cover.files())
            if len(files) != len(SIZES):
                if not test:
                    database.db.update('cover', where='id=$id and archived=$no',
                                       vars={'id': row.id, 'no': False}, failed=True)
                continue
            manager = ZipManager()
            try:
                timestamp = cover.created.timestamp() if isinstance(cover.created, datetime) else time.time()
                names = {}
                for size, path in files:
                    name = f'{row.id:010d}{"-" + size.upper() if size else ""}.jpg'
                    if not test:
                        names[size] = manager.add_file(name, path, timestamp)
            finally:
                manager.close()
            if not test:
                database.db.update('cover', where='id=$id and archived=$no and failed=$no',
                                   vars={'id': row.id, 'no': False}, archived=True, uploaded=False,
                                   filename=names[''], filename_s=names['s'],
                                   filename_m=names['m'], filename_l=names['l'])
                for _, path in files:
                    os.remove(path)


def audit(group_id, chunk_ids=(0, 100), sizes=SIZES):
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for batch_id in scope:
        for size in sizes:
            batch = Batch(group_id, batch_id, size)
            path = batch.get_abspath(group_id, batch_id, size)
            item = os.path.basename(os.path.dirname(path))
            Uploader.is_uploaded(item, os.path.basename(path), verbose=True)
